const START = new Date("2026-10-23T17:00:00+01:00").getTime();
const END = new Date("2026-10-23T23:00:00+01:00").getTime();

const countdown = setInterval(() => {
  const now = Date.now();

  // EVENT HAS FINISHED
  if (now >= END) {
    clearInterval(countdown);

    document.getElementById("days").textContent = "00";
    document.getElementById("hours").textContent = "00";
    document.getElementById("minutes").textContent = "00";
    document.getElementById("seconds").textContent = "00";

    document.getElementById("message").textContent =
      "Done! It was a successful event. See you next year!";

    document.getElementById("countdown-header").style.display = "block";

    return;
  }

  // EVENT HAS STARTED
  if (now >= START) {
    clearInterval(countdown);

    document.getElementById("days").textContent = "00";
    document.getElementById("hours").textContent = "00";
    document.getElementById("minutes").textContent = "00";
    document.getElementById("seconds").textContent = "00";

    document.getElementById("message").textContent =
      "It is here — see you in Awka!";

    document.getElementById("countdown-header").style.display = "none";

    return;
  }

  // COUNTDOWN
  const difference = START - now;

  const days = Math.floor(difference / (1000 * 60 * 60 * 24));

  const hours = Math.floor(
    (difference % (1000 * 60 * 60 * 24)) /
    (1000 * 60 * 60)
  );

  const minutes = Math.floor(
    (difference % (1000 * 60 * 60)) /
    (1000 * 60)
  );

  const seconds = Math.floor(
    (difference % (1000 * 60)) /
    1000
  );

  document.getElementById("days").textContent =
    String(days).padStart(2, "0");

  document.getElementById("hours").textContent =
    String(hours).padStart(2, "0");

  document.getElementById("minutes").textContent =
    String(minutes).padStart(2, "0");

  document.getElementById("seconds").textContent =
    String(seconds).padStart(2, "0");

}, 1000);


