/* ============================================================
   EDIT HERE. Everything below the two config blocks is plumbing.
   ============================================================ */

/* 1. Links. Replace the placeholder strings with real URLs.
      Any button still holding a REPLACE_ value shows a notice instead
      of navigating, so nothing silently goes nowhere. */
const LINKS = {
  register:  "REPLACE_REGISTER_URL",
  partner:   "REPLACE_PARTNER_PAYMENT_URL",
  testimony: "REPLACE_TESTIMONY_FORM_URL",
  shop:      "shop.html",
  card:      "card.html",
  breakfast: "REPLACE_BREAKFAST_ENQUIRY_URL"
};

/* 2. Generosity slideshow. Add an object per photo.
      Put the files in /images and keep them around 1600 x 1200. */
const SLIDES = [
  { file:"data:image/webp;base64,",   tag:"Food Bank",   caption:"Food Bank parcels going out at the conference." },
  { file:"data:image/webp;base64,",   tag:"Food Bank",   caption:"Parcels packed and ready for distribution." },
  { file:"data:image/webp;base64,",     tag:"Awards",      caption:"An award presented at the 2025 conference." },
  { file:"data:image/webp;base64,",     tag:"Awards",      caption:"Recipients with Pastor Adaeze after the presentation." },
  { file:"data:image/webp;base64,", tag:"Conference",  caption:"The panel session on day two." }
];

/* ---------------- plumbing ---------------- */
(function(){
  "use strict";
  const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /* toast */
  const toast = document.getElementById("toast");
  let toastTimer;
  function say(msg){
    toast.textContent = msg;
    toast.dataset.show = "true";
    clearTimeout(toastTimer);
    toastTimer = setTimeout(()=>{ toast.dataset.show = "false"; }, 2600);
  }

  /* links */
  document.querySelectorAll("[data-link]").forEach(el=>{
    const url = LINKS[el.dataset.link];
    if(url && !url.startsWith("REPLACE_")){
      el.href = url;
      el.target = "_blank";
      el.rel = "noopener";
    } else {
      el.addEventListener("click", e=>{
        e.preventDefault();
        say("This link is not set yet. Add it to the LINKS block in index.html.");
      });
    }
  });

  /* image slots: if a file is missing, drop the img and let the label show */
  document.querySelectorAll(".slot img").forEach(img=>{
    img.addEventListener("error", ()=> img.remove());
    if(img.complete && img.naturalWidth === 0) img.remove();
  });

  /* header menus */
  const menus = [...document.querySelectorAll("[data-menu]")];
  menus.forEach(menu=>{
    const btn = menu.querySelector("button");
    btn.addEventListener("click", e=>{
      e.stopPropagation();
      const open = menu.dataset.open === "true";
      menus.forEach(m=>{ m.dataset.open="false"; m.querySelector("button").setAttribute("aria-expanded","false"); });
      menu.dataset.open = String(!open);
      btn.setAttribute("aria-expanded", String(!open));
    });
  });
  document.addEventListener("click", ()=>{
    menus.forEach(m=>{ m.dataset.open="false"; m.querySelector("button").setAttribute("aria-expanded","false"); });
  });
  document.addEventListener("keydown", e=>{
    if(e.key === "Escape"){
      menus.forEach(m=>{ m.dataset.open="false"; m.querySelector("button").setAttribute("aria-expanded","false"); });
    }
  });

  /* mobile nav */
  const burger = document.getElementById("burger");
  const nav = document.getElementById("nav");
  if (burger && nav) {
    burger.addEventListener("click", ()=>{
      const open = nav.dataset.open === "true";
      nav.dataset.open = String(!open);
      burger.setAttribute("aria-expanded", String(!open));
      burger.setAttribute("aria-label", open ? "Open menu" : "Close menu");
    });
    nav.addEventListener("click", e=>{
      if(e.target.tagName === "A" && window.innerWidth <= 940){
        nav.dataset.open = "false";
        burger.setAttribute("aria-expanded","false");
      }
    });
  }

  /* schedule tabs */
  const tabs = document.querySelectorAll(".tab");

tabs.forEach((tab) => {
  tab.addEventListener("click", () => {

    // Update tabs
    tabs.forEach((t) => {
      t.setAttribute("aria-selected", "false");
    });

    tab.setAttribute("aria-selected", "true");

    // Hide all days
    document.querySelectorAll(".day").forEach((day) => {
      day.dataset.active = "false";
    });

    // Show selected day
    const selectedDay = document.getElementById(
      tab.getAttribute("aria-controls")
    );

    selectedDay.dataset.active = "true";
  });
});

  /* carousel */
  const car = document.getElementById("carousel");
  if (!car) return;
  let idx = 0, timer;
  car.innerHTML =
    SLIDES.map((s,i)=>(
      '<div class="slide" data-active="'+(i===0)+'">'+
        '<figure class="slot" data-file="'+s.file+' · 1600 x 1200">'+
          '<img src="'+s.file+'" alt="'+s.caption.replace(/"/g,"&quot;")+'" loading="lazy">'+
        '</figure>'+
        '<div class="cap"><p>'+s.caption+'</p><b>'+s.tag+'</b></div>'+
      '</div>'
    )).join("") +
    '<div class="controls">'+
      '<button class="arrow" type="button" data-dir="-1" aria-label="Previous photograph">&#8249;</button>'+
      '<button class="arrow" type="button" data-dir="1" aria-label="Next photograph">&#8250;</button>'+
      '<div class="dots">'+ SLIDES.map((s,i)=>'<button class="dot" type="button" aria-current="'+(i===0)+'" aria-label="Photograph '+(i+1)+'"></button>').join("") +'</div>'+
    '</div>';

  const slides = [...car.querySelectorAll(".slide")];
  const dots = [...car.querySelectorAll(".dot")];
  car.querySelectorAll(".slot img").forEach(img=>{
    img.addEventListener("error", ()=> img.remove());
  });

  function show(n){
    idx = (n + slides.length) % slides.length;
    slides.forEach((s,i)=> s.dataset.active = String(i===idx));
    dots.forEach((d,i)=> d.setAttribute("aria-current", String(i===idx)));
  }
  car.querySelectorAll(".arrow").forEach(b=>{
    b.addEventListener("click", ()=>{ show(idx + Number(b.dataset.dir)); restart(); });
  });
  dots.forEach((d,i)=> d.addEventListener("click", ()=>{ show(i); restart(); }));

  function restart(){
    if(reduced) return;
    clearInterval(timer);
    timer = setInterval(()=> show(idx+1), 6500);
  }
  car.addEventListener("mouseenter", ()=> clearInterval(timer));
  car.addEventListener("mouseleave", restart);
  restart();

  /* copy account number */
  const copyBtn = document.getElementById("copyBtn");
  copyBtn.addEventListener("click", async ()=>{
    const num = document.getElementById("acct").textContent.trim();
    try{
      await navigator.clipboard.writeText(num);
      copyBtn.textContent = "Copied";
      setTimeout(()=> copyBtn.textContent = "Copy", 2000);
    }catch(err){
      say("Account number: " + num);
    }
  });

  document.getElementById("yr").textContent = new Date().getFullYear();
})();











  